        public bool SendEmailMailTrapAsync(string userEmail, string body)
        {

            try
            {

                var client = new SmtpClient("smtp.mailtrap.io", 2525)
                {
                    Credentials = new NetworkCredential("fbc8f7dbb87a2b", "c0fb9241b03c87"),
                    EnableSsl = true
                };

                client.Send("non-reply@example.com", userEmail, "Account Verification", body);

                return true;
            }
            catch (Exception ex)
            {
                LoggerService serviceLogger = new LoggerService();
                serviceLogger.LogError("Error while attempting to send email with mail " + ex.Message + " inner exception " + ex.InnerException);
                return false;
            }

        }

